 function snapshot(){return {format:'coral-preparation-draft-1',context:captured,models:jobs.map(j=>({model:j.model,selected:j.selected})),rawCsv,mapping,encoding,activities,corrections,reviewer,events,associationProfile,csvSourceHash,csvPending,sourceBytesBase64:fileBytes?encode(fileBytes):undefined};}
