 async function draftDb(){return await new Promise<IDBDatabase>((resolve,reject)=>{const r=indexedDB.open('ifc-coral-preparation',1);r.onupgradeneeded=()=>r.result.createObjectStore('drafts');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
